mapper.select:
SELECT id
FROM runrun_v2.courier_certifications
WHERE courier_id = #{courierId,jdbcType=BIGINT}

mapper.update:
UPDATE runrun_v2.courier_certifications
SET updated_at = now()
WHERE id = #{certificationId,jdbcType=BIGINT}
    AND version = #{expectedVersion,jdbcType=BIGINT}

mapper.select:
SELECT count(*)
FROM runrun_v2.evidence_deletion_audits
WHERE certification_id = #{certificationId,jdbcType=BIGINT}
    AND resource_id = #{resourceId,jdbcType=VARCHAR}
    AND status = 'DELETING'
